import json
import numpy as np
import pandas as pd
from pathlib import Path
from scipy.signal import firwin, resample_poly

# ============================================================
# 1. CONFIGURATION
# ============================================================

speed = 100

BASE_DIR = Path(
    fr"C:\Users\vishw\Documents\Vibration Dataset\{speed}"
)

# Read the shared split generated by main.py.
SPLIT_FILE = BASE_DIR / "dataset_split.json"
if not SPLIT_FILE.exists():
    raise FileNotFoundError(
        f"{SPLIT_FILE} not found. Run main.py first to generate the dataset split."
    )
with open(SPLIT_FILE, "r", encoding="utf-8") as f:
    DATASET_SPLIT = json.load(f)
SELECTED_COLUMNS = DATASET_SPLIT["TRAIN_COLUMNS"]

CHANNELS = [1, 2, 3]

# Each entry describes the folder and filename stem for one fault class.
# The channel number is inserted automatically.
CLASS_FILES = {
    "HEALTHY": {
        "folder": "healthy 2",
        "data_stem": f"Vibration_Motor-2_{speed}_time-healthy 2",
        "calibration_stem": "healthy_2",
    },
    "BPFO": {
        "folder": "bearing bpfo 2",
        "data_stem": f"Vibration_Motor-2_{speed}_time-bearing bpfo 2",
        "calibration_stem": "bearing_bpfo_2",
    },
    "BPFI": {
        "folder": "bearing bpfi 2",
        "data_stem": f"Vibration_Motor-2_{speed}_time-bearing bpfi 2",
        "calibration_stem": "bearing_bpfi_2",
    },
    "STATOR_SHORT": {
        "folder": "stator short 1",
        "data_stem": f"Vibration_Motor-2_{speed}_time-stator short 1",
        "calibration_stem": "stator_short_1",
    },
    "BROKEN_ROTOR_BAR": {
        "folder": "broken rotor bar",
        "data_stem": f"Vibration_Motor-2_{speed}_time-broken rotor bar",
        "calibration_stem": "broken_rotor_bar",
    },
}

# ============================================================
# 2. SIGNAL-PROCESSING SETTINGS
# ============================================================

FS_ORIGINAL = 20000
FS = 10000
FFT_SIZE = 1024
NUM_BLOCKS = 117

BANDS = [
    (0, 500),
    (500, 1000),
    (1000, 1500),
    (1500, 2000),
    (2000, 2500),
    (2500, 3000),
    (3000, 3500),
    (3500, 4000),
    (4000, 4500),
    (4500, 5000),
]

BAND_NAMES = [f"{low}_{high}Hz" for low, high in BANDS]
FREQ_COLS = [f"{name}_freq_Hz" for name in BAND_NAMES]
MAG_COLS = [f"{name}_mag" for name in BAND_NAMES]

ALL_FEATURE_COLS = []
for freq_col, mag_col in zip(FREQ_COLS, MAG_COLS):
    ALL_FEATURE_COLS.extend([freq_col, mag_col])

FREQ_RESOLUTION = FS / FFT_SIZE
window = np.hanning(FFT_SIZE)

frequencies = np.fft.rfftfreq(FFT_SIZE, d=1 / FS)

# Anti-alias filter for downsampling from 20 kHz to 10 kHz.
NUMTAPS = 401
fir_coefficients = firwin(
    numtaps=NUMTAPS,
    cutoff=4750,
    fs=FS_ORIGINAL,
    window=("kaiser", 8.6),
)

# Precompute the FFT-bin mask for each band.
BAND_MASKS = {}
for (low, high), band_name in zip(BANDS, BAND_NAMES):
    mask = (frequencies >= low) & (frequencies < high)
    if not np.any(mask):
        raise ValueError(f"No FFT bins found in band {band_name}")
    BAND_MASKS[band_name] = mask


# ============================================================
# 3. PROCESS ONE RECORDING
# ============================================================

def process_recording(signal):
    signal = np.asarray(signal, dtype=float)

    if signal.ndim != 1:
        raise ValueError("Each recording must be a one-dimensional signal.")
    if not np.all(np.isfinite(signal)):
        raise ValueError("Signal contains missing or non-finite values.")

    # Remove DC component.
    signal = signal - np.mean(signal)

    # Anti-alias filtering and downsampling: 20 kHz -> 10 kHz.
    signal_downsampled = resample_poly(
        signal,
        up=1,
        down=2,
        window=fir_coefficients,
    )

    required_samples = NUM_BLOCKS * FFT_SIZE
    if len(signal_downsampled) < required_samples:
        raise ValueError(
            f"Not enough downsampled samples: {len(signal_downsampled)} "
            f"available, {required_samples} required."
        )

    # Use exactly 117 complete 1024-point FFT blocks.
    signal_downsampled = signal_downsampled[:required_samples]

    block_peak_frequencies = {name: [] for name in BAND_NAMES}
    block_peak_magnitudes = {name: [] for name in BAND_NAMES}

    for block in range(NUM_BLOCKS):
        start = block * FFT_SIZE
        segment = signal_downsampled[start:start + FFT_SIZE]

        # Hann window and 1024-point real FFT.
        X = np.fft.rfft(segment * window)
        magnitude = np.abs(X)

        # Find the strongest FFT bin in each frequency band.
        for band_name in BAND_NAMES:
            mask = BAND_MASKS[band_name]
            band_magnitudes = magnitude[mask]
            band_frequencies = frequencies[mask]

            peak_index = int(np.argmax(band_magnitudes))
            block_peak_frequencies[band_name].append(
                band_frequencies[peak_index]
            )
            block_peak_magnitudes[band_name].append(
                band_magnitudes[peak_index]
            )

    # One recording-level feature vector: median across 117 FFT blocks.
    summary = {}
    for band_name in BAND_NAMES:
        summary[f"{band_name}_freq_Hz"] = float(
            np.median(block_peak_frequencies[band_name])
        )
        summary[f"{band_name}_mag"] = float(
            np.median(block_peak_magnitudes[band_name])
        )

    return summary


# ============================================================
# 4. CALCULATE CALIBRATION STATISTICS FOR ONE CLASS/CHANNEL
# ============================================================

def calculate_calibration(results_df):
    median_values = results_df[ALL_FEATURE_COLS].median()
    mad_values = pd.Series(index=ALL_FEATURE_COLS, dtype=float)
    sigma_values = pd.Series(index=ALL_FEATURE_COLS, dtype=float)
    variance_values = pd.Series(index=ALL_FEATURE_COLS, dtype=float)
    tolerance_values = pd.Series(index=ALL_FEATURE_COLS, dtype=float)
    lower_values = pd.Series(index=ALL_FEATURE_COLS, dtype=float)
    upper_values = pd.Series(index=ALL_FEATURE_COLS, dtype=float)

    for col in ALL_FEATURE_COLS:
        median_value = float(median_values[col])

        deviations = np.abs(
            results_df[col].to_numpy(dtype=float) - median_value
        )
        mad = float(np.median(deviations))

        # Robust Gaussian-kernel parameters:
        # mu = median; sigma = 1.4826 * MAD; variance = sigma^2.
        sigma = 1.4826 * mad
        variance = sigma ** 2

        # Retain the interval tolerances from the previous method.
        if col in FREQ_COLS:
            tolerance = max(FREQ_RESOLUTION, 2.0 * mad)
        else:
            tolerance = 2.0 * mad

        mad_values[col] = mad
        sigma_values[col] = sigma
        variance_values[col] = variance
        tolerance_values[col] = tolerance
        lower_values[col] = median_value - tolerance
        upper_values[col] = median_value + tolerance

    rows = []
    summary_items = [
        ("MEDIAN", median_values),
        ("MAD", mad_values),
        ("GAUSSIAN_SIGMA", sigma_values),
        ("GAUSSIAN_VARIANCE", variance_values),
        ("TOLERANCE", tolerance_values),
        ("LOWER_THRESHOLD", lower_values),
        ("UPPER_THRESHOLD", upper_values),
    ]

    for row_name, values in summary_items:
        row = {"CSV_Column": row_name}
        for col in ALL_FEATURE_COLS:
            row[col] = float(values[col])
        rows.append(row)

    summary_df = pd.DataFrame(rows)
    return summary_df


# ============================================================
# 5. PROCESS ONE CLASS AND ONE CHANNEL
# ============================================================

def process_class_channel(class_name, class_info, channel):
    folder = BASE_DIR / class_info["folder"]

    input_file = folder / (
        f'{class_info["data_stem"]}-ch{channel}.csv'
    )
    # Store the calibration output in the same class folder using
    # a short, consistent filename.
    output_file = folder / f"thresholds_ch{channel}.csv"

    print("\n" + "=" * 72)
    print(f"CLASS: {class_name} | CHANNEL: {channel}")
    print("=" * 72)
    print("Input:", input_file)

    if not input_file.is_file():
        raise FileNotFoundError(f"Input file not found:\n{input_file}")

    # The source CSV is expected to have column headers, as in the
    # original script. SELECTED_COLUMNS are 1-based column numbers.
    df = pd.read_csv(input_file)

    if max(SELECTED_COLUMNS) > len(df.columns):
        raise ValueError(
            f"{input_file.name} has {len(df.columns)} columns, but "
            f"column {max(SELECTED_COLUMNS)} was requested."
        )

    recording_results = []

    for csv_column in SELECTED_COLUMNS:
        print(f"Processing CSV column {csv_column}...")

        signal = pd.to_numeric(
            df.iloc[:, csv_column - 1],
            errors="coerce",
        ).to_numpy(dtype=float)

        if not np.all(np.isfinite(signal)):
            raise ValueError(
                f"Non-numeric or missing samples in "
                f"{input_file.name}, column {csv_column}."
            )

        features = process_recording(signal)
        features["CSV_Column"] = csv_column
        recording_results.append(features)

    results_df = pd.DataFrame(recording_results)
    results_df = results_df[["CSV_Column"] + ALL_FEATURE_COLS]

    summary_df = calculate_calibration(results_df)

    # Save the eight recording feature vectors and calibration summary rows.
    final_df = pd.concat(
        [results_df, summary_df],
        ignore_index=True,
    )
    final_df.to_csv(output_file, index=False)

    print("\nRecording-level feature results:")
    print(results_df.to_string(index=False))

    print("\nCalibration statistics:")
    print(summary_df.to_string(index=False))

    print("\nSaved threshold/calibration file:", output_file)

    # Return a compact metadata row for the overall run report.
    return {
        "Class": class_name,
        "Channel": channel,
        "Input_File": str(input_file),
        "Output_File": str(output_file),
        "Training_Columns": ", ".join(map(str, SELECTED_COLUMNS)),
        "Recordings_Processed": len(recording_results),
        "Status": "SUCCESS",
    }


# ============================================================
# 6. MAIN: ALL 5 CLASSES x ALL 3 CHANNELS
# ============================================================

def main():
    print("FFT-based vibration feature calibration")
    print("----------------------------------------")
    print(f"Sampling rate after downsampling: {FS} Hz")
    print(f"FFT size: {FFT_SIZE}")
    print(f"FFT frequency resolution: {FREQ_RESOLUTION:.6f} Hz")
    print(f"FFT blocks per recording: {NUM_BLOCKS}")
    print(f"Training CSV columns (1-based): {SELECTED_COLUMNS}")
    print(f"Channels: {CHANNELS}")
    print(f"Total class/channel combinations: "
          f"{len(CLASS_FILES) * len(CHANNELS)}")

    run_report = []

    for class_name, class_info in CLASS_FILES.items():
        for channel in CHANNELS:
            report_row = process_class_channel(
                class_name,
                class_info,
                channel,
            )
            run_report.append(report_row)

    report_df = pd.DataFrame(run_report)
    report_path = BASE_DIR / "feature_calibration_run_report.csv"
    report_df.to_csv(report_path, index=False)

    print("\n" + "=" * 72)
    print("ALL CALIBRATION JOBS COMPLETED")
    print("=" * 72)
    print(report_df.to_string(index=False))
    print("\nRun report saved at:", report_path)


if __name__ == "__main__":
    main()
